package com.insight.quantlife.tests;
import android.app.*;import android.os.*;import org.json.*;import java.io.*;import java.text.*;import java.util.*;import com.insight.quantlife.*;
/** Disposable synthetic AVD only. Actual native database and WebView; no external model. */
public class WorkFactsTest extends WorkClockTest {
 final String fixtureId="work-facts-screen";String date;
 JSONObject fixture()throws Exception{return new JSONObject().put("id",fixtureId).put("type","work").put("date",date).put("title","合成工作班次").put("workStart",date+"T09:38:00").put("workEnd",date+"T19:13:00").put("breaks",new JSONArray().put(new JSONObject().put("start",date+"T12:35:00").put("end",date+"T14:05:00"))).put("note","合成进展记录").put("tags",new JSONArray()).put("durationMinutes",485);}
 void seedFacts()throws Exception{holdAutomation();check(getTargetContext().getPackageManager().getPackageInfo(getTargetContext().getPackageName(),0).versionName.equals("1.7.3"),"Baseline signed 1.7.3");JSONObject data=init();try(TrackStore ts=new TrackStore(getTargetContext())){data.put("raw",ts.diagnostics("2026-12-15").getJSONArray("rawPoints")).put("gpx",ts.gpx("2026-12-15"));}try(FileOutputStream f=getTargetContext().openFileOutput("work-facts-upgrade.json",0)){f.write(data.toString().getBytes("UTF-8"));}}
 String last()throws Exception{JSONArray a=chat().getJSONArray("messages");return a.getJSONObject(a.length()-1).getString("text");}
 void factsMock()throws Exception{h.js("window.__calls=[];window.__orig=LifeNative;LifeNative={call:function(action,payload,rid){if(action!=='ask'){__orig.call(action,payload,rid);return;}const p=JSON.parse(payload);__calls.push(p);const raw=p.tool.name==='plan_record_search'?{intent:'history',topic:'',keywords:[],dateStart:__date,dateEnd:__date,recordTypes:['work']}:{answer:'你09:38上班，19:13下班，午休90分钟，净工作6小时35分。\\n\\n合成进展记录已完成，保留这段解释。',records:[],citations:['work-facts-screen'],actions:[]};setTimeout(()=>nativeReply({id:rid,data:{text:JSON.stringify(raw),model:'synthetic-wrong-work-answer'}}),20)}}");}
 void verifyUpgrade()throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=getTargetContext().openFileInput("work-facts-upgrade.json")){byte[] buf=new byte[4096];int n;while((n=in.read(buf))>0)out.write(buf,0,n);}JSONObject old=new JSONObject(out.toString("UTF-8")),current=init();check(getTargetContext().getPackageManager().getPackageInfo(getTargetContext().getPackageName(),0).versionName.equals("1.7.4"),"Signed 1.7.4 cover installation");for(String k:new String[]{"records","messages","wikiPages","chatSession"})check(old.get(k).toString().equals(current.get(k).toString()),"Upgrade preserves "+k);JSONObject a=old.getJSONObject("settings"),b=current.getJSONObject("settings");a.remove("wikiAutomation");b.remove("wikiAutomation");check(a.toString().equals(b.toString()),"Upgrade preserves all prior model/current-search settings");try(TrackStore ts=new TrackStore(getTargetContext())){check(old.getString("gpx").equals(ts.gpx("2026-12-15"))&&old.getJSONArray("raw").toString().equals(ts.diagnostics("2026-12-15").getJSONArray("rawPoints").toString()),"Upgrade preserves raw GPS and D trajectory");}}
 void factsFlow()throws Exception{
  holdAutomation();if(!phase.equals("flow"))verifyUpgrade();date=new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date());
  // This AVD contains only synthetic work records from earlier automated suites.
  JSONArray records=init().getJSONArray("records");for(int i=0;i<records.length();i++)if(records.getJSONObject(i).optString("type").equals("work"))h.call("deleteRecord",new JSONObject().put("id",records.getJSONObject(i).getString("id")));
  h.call("saveRecord",new JSONObject().put("record",fixture()).put("allowDuplicate",true));
  JSONObject noKey=new JSONObject().put("id","openai").put("label","合成无Key配置").put("baseUrl","https://example.invalid/v1").put("model","synthetic-model").put("protocol","chat").put("effort","off").put("apiKey","");h.call("saveSettings",new JSONObject().put("settings",new JSONObject().put("profile",noKey)));h.call("newChat",new JSONObject());reload();holdAutomation();factsMock();h.js("__date="+JSONObject.quote(date));click("[data-page=chat]");
  check(!init().getJSONObject("settings").getJSONObject("profiles").getJSONObject("openai").optBoolean("keyConfigured"),"Factual query fixture has no configured model key");
  sendText("我今天下班了嘛");check(last().contains("已记录下班")&&last().contains("8 小时 5 分")&&!last().contains("6小时35分"),"Exact screenshot state question uses native truth, not model arithmetic");jsCheck("__calls.length===0","State question makes zero model/API requests");check(find(fixtureId).getInt("durationMinutes")==485,"Question does not mutate original shift");
  sendText("今天工作了多久");check(last().contains("9 小时 35 分")&&last().contains("1 小时 30 分")&&last().contains("8 小时 5 分"),"Gross/rest/net reported separately with one deduction");Thread.sleep(700);h.screenshot("work-facts-answer-1.7.4.png");
  click(".chat-message:last-child .citation");jsCheck("document.querySelector('#editor').innerText.includes('8小时5分')&&document.querySelector('#editor').innerText.includes('09:38')&&document.querySelector('#editor').innerText.includes('19:13')","Actual citation detail agrees with chat clock totals");click("#close-editor");
  // Edit native data without refreshing WebView state: next question must fetch current DB.
  JSONObject changed=find(fixtureId);changed.put("workEnd",date+"T20:00:00");h.call("saveRecord",new JSONObject().put("record",changed).put("allowDuplicate",true));sendText("今天工作多久");check(last().contains("8 小时 52 分")&&!last().contains("8 小时 5 分"),"Query refreshes native records, not stale JS or conversation memory");jsCheck("__calls.length===0","All direct factual questions run locally without key");
  h.call("saveRecord",new JSONObject().put("record",fixture()).put("allowDuplicate",true));
  h.call("saveSettings",new JSONObject().put("settings",new JSONObject().put("profile",model("SYNTHETIC-ONLY"))));reload();holdAutomation();factsMock();h.js("__date="+JSONObject.quote(date));click("[data-page=chat]");
  sendText("请回顾今天的工作节奏并谈谈启发");check(last().contains("8 小时 5 分")&&!last().contains("6小时35分")&&last().contains("保留这段解释"),"Deliberately wrong model numeric paragraph replaced, interpretive text retained");jsCheck("__calls.some(p=>p.tool.name==='prepare_life_records'&&p.messages[0].content.includes('netRestAlreadyDeducted'))","Real model request includes explicit authoritative timing basis");
  JSONObject before=find(fixtureId);sendText("我现在已经下班了 然后你可以帮我打一下");check(last().contains("19:13 下班")&&last().contains("不需要重复打卡")&&last().contains("8 小时 5 分"),"Repeated colloquial end-clock gives stored end and correction instructions");check(before.toString().equals(find(fixtureId).toString()),"Already-ended clock never overwrites or creates native record");jsCheck("!document.querySelector('[data-confirm-change]')&&!document.querySelector('[data-save-candidate]')","Repeated ended clock creates no write preview");Thread.sleep(700);h.js("ChatUI.bottom()");Thread.sleep(350);h.screenshot("work-facts-ended-1.7.4.png");
  jsCheck("!document.querySelector('.app-header')&&!document.querySelector('.chat-title')&&getComputedStyle(document.querySelector('.chat-context-label')).color==='rgb(33, 106, 84)'","No top brand bar and original green styling retained");jsCheck("document.documentElement.scrollWidth<=innerWidth+1","Grounded work answer fits phone width");
 }
 @Override public void onStart(){Bundle result=new Bundle();try{h=new MainHost(this);h.open();if(phase.equals("seed"))seedFacts();else if(phase.equals("keyboard"))keyboardUi();else factsFlow();result.putString("stream","PASS "+passed+" work-facts/native/UI checks; phase="+phase+"; no real model API\n");finish(Activity.RESULT_OK,result);}catch(Throwable e){result.putString("stream","FAIL after "+passed+": "+e+"\n");finish(Activity.RESULT_CANCELED,result);}}
}
